class Solution {
    public int compress(char[] chars) {
        int write = 0, i = 0, n = chars.length;
        while (i < n) {
            char ch = chars[i];
            int count = 0;
            while (i < n && chars[i] == ch) {
                i++; count++;
            }
            chars[write++] = ch;
            if (count > 1) {
                for (char c : String.valueOf(count).toCharArray()) {
                    chars[write++] = c;
                }
            }
        }
        return write;
    }
}

var compress = function(chars) {
    let write = 0, i = 0, n = chars.length;
    while (i < n) {
        const ch = chars[i];
        let count = 0;
        while (i < n && chars[i] === ch) {
            i++; count++;
        }
        chars[write++] = ch;
        if (count > 1) {
            const s = String(count);
            for (let k = 0; k < s.length; k++) {
                chars[write++] = s[k];
            }
        }
    }
    return write;
};
